<template><section class="duplicate-photos"><div class="tools"><button :class="{active:!reviewed}" @click="switchTab(false)">확인 필요</button><button :class="{active:reviewed}" @click="switchTab(true)">확인 완료</button><button :disabled="busy" @click="load">새로고침</button></div><p class="hint">사진은 순차적으로 검사됩니다. 유사 사진은 동일인·사칭 판정이 아니며, 회원 상세에서 셀피를 요청할 수 있습니다.</p><p v-if="error" role="alert">{{error}}</p><p v-if="busy">불러오는 중…</p><p v-else-if="!rows.length">{{reviewed?'확인 완료한 사진이 없습니다.':'현재 확인할 의심 사진이 없습니다.'}}</p><article v-for="row in rows" :key="row.id"><header><strong>{{row.exact?'동일 사진 의심':'유사 사진 의심'}}</strong><span>{{new Date(row.detectedAt).toLocaleString('ko-KR')}}</span></header><div class="pair"><figure v-for="member in [row.left,row.right]" :key="member.id"><img v-private-src.admin="member.photo" loading="lazy" tabindex="0" role="button" title="사진 확대" :alt="member.nickname+' 프로필 사진'"/><figcaption><b>{{member.nickname}}</b> <small>#{{member.id}} · {{states[member.status]||member.status}}</small><button @click="$emit('member',member.id)">회원 상세 · 셀피 요청</button></figcaption></figure></div><footer><button :disabled="busy" @click="mark(row)">{{reviewed?'확인 필요로 되돌리기':'확인 완료'}}</button></footer></article><div class="tools"><button :disabled="busy||page===0" @click="page--;load()">이전</button><span>{{page+1}}</span><button :disabled="busy||rows.length<20" @click="page++;load()">다음</button></div></section></template>
<script setup>
import {ref,onMounted,onUnmounted} from 'vue';import api from '../../api/api';defineEmits(['member']);const rows=ref([]),reviewed=ref(false),page=ref(0),busy=ref(false),error=ref('');let epoch=0;const states={ACTIVE:'활동 중',PENDING_REVIEW:'가입 심사 중',REJECTED:'가입 반려',SUSPENDED:'이용 제한'};
async function load(){const n=++epoch;busy.value=true;error.value='';try{const data=(await api.get('/admin/photo-duplicates',{params:{reviewed:reviewed.value,page:page.value}})).data;if(n===epoch)rows.value=data;}catch(e){if(n===epoch){rows.value=[];error.value=e.response?.data?.message||'사진 목록을 불러오지 못했습니다.';}}finally{if(n===epoch)busy.value=false;}}
function switchTab(value){reviewed.value=value;page.value=0;load();}async function mark(row){busy.value=true;error.value='';try{await api.put('/admin/photo-duplicates/'+row.id,{reviewed:!row.reviewed});await load();}catch{error.value='처리하지 못했습니다. 다시 시도해 주세요.';busy.value=false;}}onMounted(load);onUnmounted(()=>epoch++);
</script><style scoped>.tools{display:flex;gap:10px;align-items:center;flex-wrap:wrap}button{padding:10px 14px;border:1px solid #ddd;border-radius:9px;background:white;color:#51443a;cursor:pointer}button.active{background:#bd7452;color:white;border-color:#bd7452}button:disabled{opacity:.5}.hint{color:#7b838b;font-size:13px;line-height:1.7}article{background:white;border:1px solid #e7e9ed;border-radius:14px;padding:20px;margin:18px 0}header{display:flex;gap:12px;justify-content:space-between;flex-wrap:wrap}header span,small{font-size:12px;color:#7d8790}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:18px 0}figure{margin:0;min-width:0}img{width:100%;height:260px;object-fit:contain;background:#f2f1ef;border-radius:10px;cursor:zoom-in}figcaption{display:grid;gap:8px;margin-top:10px}footer{text-align:right}[role=alert]{color:#a33}@media(max-width:600px){article{padding:12px}.pair{gap:10px}img{height:190px}figcaption button{padding:8px;font-size:11px}}</style>
